Procedure Posting(Cancel, PostingMode) {
    foreach (row In Goods) {
        m = RegisterRecords.Stock.Add();
        m.RecordType = AccumulationRecordType.Receipt;
        m.Period = Date;
        m.Item = row.Item;
        m.Quantity = row.Quantity;
    }
}
